  #wrap{position:relative;width:100vw;height:100vh;}
  canvas{display:block;width:100%;height:100%;cursor:crosshair;}
  .ui{position:absolute;font-family:'Press Start 2P',monospace;color:#fff;user-select:none;pointer-events:none;}
  #hud{top:14px;left:16px;font-size:clamp(11px,1.6vw,18px);line-height:1.9;text-shadow:0 2px 0 #000;}
  #hud .lbl{color:#ffd76e;font-size:.72em;letter-spacing:1px;}
  #lives{letter-spacing:6px;color:#ff5d5d;}
  #combo{top:14px;right:16px;font-size:clamp(10px,1.4vw,16px);color:#7bffb2;text-shadow:0 2px 0 #000;opacity:0;transition:opacity .25s;}
  #overlay{inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:26px;background:rgba(9,7,20,.78);backdrop-filter:blur(3px);pointer-events:auto;text-align:center;}
  #overlay h1{margin:0;font-family:'Press Start 2P',monospace;font-size:clamp(18px,4vw,40px);color:#ffd76e;text-shadow:0 4px 0 #6b2f00, 0 0 24px rgba(255,215,110,.35);}
  #overlay p{margin:0;font-family:'Press Start 2P',monospace;font-size:clamp(9px,1.5vw,14px);color:#cfd2ff;line-height:2;}
  #overlay .big{font-size:clamp(14px,2.4vw,22px);color:#7bffb2;}
  #startBtn{font-family:'Press Start 2P',monospace;font-size:clamp(12px,2vw,20px);padding:16px 34px;color:#1a1206;background:#ffd76e;border:0;border-radius:4px;box-shadow:0 6px 0 #a8781a;cursor:pointer;}
  #startBtn:hover{filter:brightness(1.08);}
  #startBtn:active{transform:translateY(4px);box-shadow:0 2px 0 #a8781a;}
  .hidden{display:none !important;}
  @keyframes shakehud{0%,100%{transform:translateX(0)}25%{transform:translateX(-4px)}75%{transform:translateX(4px)}}
